macro_rules! FutureExt {
    () => {
        # [doc = " Extension trait for [`Future`]."] pub trait FutureExt : Future { # [doc = " A convenience for calling [`Future::poll()`] on `!`[`Unpin`] types."] fn poll (& mut self , cx : & mut Context < '_ >) -> Poll < Self :: Output > where Self : Unpin , { Future :: poll (Pin :: new (self) , cx) } # [doc = " Returns the result of `self` or `other` future, preferring `self` if both are ready."] # [doc = ""] # [doc = " If you need to treat the two futures fairly without a preference for either, use the"] # [doc = " [`race()`] function or the [`FutureExt::race()`] method."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::future::{pending, ready, FutureExt};"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " assert_eq!(ready(1).or(pending()).await, 1);"] # [doc = " assert_eq!(pending().or(ready(2)).await, 2);"] # [doc = ""] # [doc = " // The first future wins."] # [doc = " assert_eq!(ready(1).or(ready(2)).await, 1);"] # [doc = " # })"] # [doc = " ```"] fn or < F > (self , other : F) -> Or < Self , F > where Self : Sized , F : Future < Output = Self :: Output > , { Or { future1 : self , future2 : other , } } # [doc = " Returns the result of `self` or `other` future, with no preference if both are ready."] # [doc = ""] # [doc = " Each time [`Race`] is polled, the two inner futures are polled in random order. Therefore,"] # [doc = " no future takes precedence over the other if both can complete at the same time."] # [doc = ""] # [doc = " If you have preference for one of the futures, use the [`or()`] function or the"] # [doc = " [`FutureExt::or()`] method."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::future::{pending, ready, FutureExt};"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " assert_eq!(ready(1).race(pending()).await, 1);"] # [doc = " assert_eq!(pending().race(ready(2)).await, 2);"] # [doc = ""] # [doc = " // One of the two futures is randomly chosen as the winner."] # [doc = " let res = ready(1).race(ready(2)).await;"] # [doc = " # })"] # [doc = " ```"] # [cfg (all (feature = "std" , feature = "race"))] fn race < F > (self , other : F) -> Race < Self , F > where Self : Sized , F : Future < Output = Self :: Output > , { Race { future1 : self , future2 : other , rng : Rng :: new () , } } # [doc = " Catches panics while polling the future."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::future::FutureExt;"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " let fut1 = async {}.catch_unwind();"] # [doc = " let fut2 = async { panic!() }.catch_unwind();"] # [doc = ""] # [doc = " assert!(fut1.await.is_ok());"] # [doc = " assert!(fut2.await.is_err());"] # [doc = " # })"] # [doc = " ```"] # [cfg (feature = "std")] fn catch_unwind (self) -> CatchUnwind < Self > where Self : Sized + UnwindSafe , { CatchUnwind { inner : self } } # [doc = " Boxes the future and changes its type to `dyn Future + Send + 'a`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::future::{self, FutureExt};"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " let a = future::ready('a');"] # [doc = " let b = future::pending();"] # [doc = ""] # [doc = " // Futures of different types can be stored in"] # [doc = " // the same collection when they are boxed:"] # [doc = " let futures = vec![a.boxed(), b.boxed()];"] # [doc = " # })"] # [doc = " ```"] # [cfg (feature = "alloc")] fn boxed < 'a > (self) -> Pin < Box < dyn Future < Output = Self :: Output > + Send + 'a > > where Self : Sized + Send + 'a , { Box :: pin (self) } # [doc = " Boxes the future and changes its type to `dyn Future + 'a`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::future::{self, FutureExt};"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " let a = future::ready('a');"] # [doc = " let b = future::pending();"] # [doc = ""] # [doc = " // Futures of different types can be stored in"] # [doc = " // the same collection when they are boxed:"] # [doc = " let futures = vec![a.boxed_local(), b.boxed_local()];"] # [doc = " # })"] # [doc = " ```"] # [cfg (feature = "alloc")] fn boxed_local < 'a > (self) -> Pin < Box < dyn Future < Output = Self :: Output > + 'a > > where Self : Sized + 'a , { Box :: pin (self) } }
    };
}

FutureExt!();